import{_ as a,o as s,c as i,a6 as n}from"./chunks/framework.BrkgobfX.js";const k=JSON.parse('{"title":"14 · 精细化上下文管理：外科手术，而非大刀阔斧","description":"自动压缩是钝器——它摘要掉一整段、还击穿缓存。有时你只想精准处理“那个占了两万 token 的巨型工具结果”。讲清三把手术刀：工具结果预算(超限外置)、按 tool_use_id 定点删除的 microcompact、以及内容外置引用，以及它们如何在减负的同时保住缓存。","frontmatter":{"title":"14 · 精细化上下文管理：外科手术，而非大刀阔斧","description":"自动压缩是钝器——它摘要掉一整段、还击穿缓存。有时你只想精准处理“那个占了两万 token 的巨型工具结果”。讲清三把手术刀：工具结果预算(超限外置)、按 tool_use_id 定点删除的 microcompact、以及内容外置引用，以及它们如何在减负的同时保住缓存。","source":"https://daiw.org/manual/llm-to-agent/context-compaction"},"headers":[],"relativePath":"manual/agent/llm-to-agent/context-compaction.md","filePath":"manual/agent/llm-to-agent/context-compaction.md"}'),e={name:"manual/agent/llm-to-agent/context-compaction.md"};function l(o,t,r,p,h,d){return s(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="_14-·-精细化上下文管理-外科手术-而非大刀阔斧" tabindex="-1">14 · 精细化上下文管理：外科手术，而非大刀阔斧 <a class="header-anchor" href="#_14-·-精细化上下文管理-外科手术-而非大刀阔斧" aria-label="Permalink to &quot;14 · 精细化上下文管理：外科手术，而非大刀阔斧&quot;">​</a></h1><blockquote><p>自动压缩是钝器——它摘要掉一整段、还击穿缓存。有时你只想精准处理“那个占了两万 token 的巨型工具结果”。讲清三把手术刀：工具结果预算(超限外置)、按 tool_use_id 定点删除的 microcompact、以及内容外置引用，以及它们如何在减负的同时保住缓存。</p></blockquote><p><a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">上一篇的自动压缩</a>很有效，但它是<strong>钝器</strong>：一刀把边界前的所有历史摘要成一段，损失了全部细节，还<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">击穿了缓存</a>。很多时候，上下文膨胀其实只源于<strong>几个具体的“胖子”</strong>——你想要的是精准切除它们，而不是把整段历史推平。这一篇，讲三把外科手术刀。</p><h2 id="一、背景-膨胀往往是-局部-的" tabindex="-1">一、背景：膨胀往往是“局部”的 <a class="header-anchor" href="#一、背景-膨胀往往是-局部-的" aria-label="Permalink to &quot;一、背景：膨胀往往是“局部”的&quot;">​</a></h2><p>观察真实 Agent 的上下文，你会发现膨胀高度<strong>不均匀</strong>：</p><ul><li>大部分消息(用户的话、模型的推理、小工具结果)都不大。</li><li>但<strong>个别工具结果是巨无霸</strong>：一次 <code>read_file</code> 读进来一个五千行的文件、一条 <code>npm test</code> 刷了两千行日志、一次 <code>git diff</code> 几百个改动。<strong>单单几个这样的结果，就可能占掉上下文的大半。</strong></li></ul><p>对这种“局部肥胖”，用<a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">全量压缩</a>是杀鸡用牛刀：你为了削掉那两万 token 的日志，把整段对话的细节全摘要没了，还废了缓存。<strong>更好的办法是精准地只处理那几个胖子。</strong></p><h2 id="二、三把手术刀" tabindex="-1">二、三把手术刀 <a class="header-anchor" href="#二、三把手术刀" aria-label="Permalink to &quot;二、三把手术刀&quot;">​</a></h2><h3 id="手术刀一-工具结果预算-超限就外置" tabindex="-1">手术刀一：工具结果预算(超限就外置) <a class="header-anchor" href="#手术刀一-工具结果预算-超限就外置" aria-label="Permalink to &quot;手术刀一：工具结果预算(超限就外置)&quot;">​</a></h3><p>最前置的一招：<strong>给每个工具结果设一个大小上限。</strong> 还记得<a href="/Front2Full/manual/agent/llm-to-agent/tool-abstraction">04 篇</a>工具接口里那个 <code>maxResultSizeChars</code> 吗？就是干这个的。当一个结果超过上限：</p><ol><li>把<strong>完整结果写到外部</strong>(磁盘上一个临时文件)。</li><li>只给模型一个<strong>截断预览 + 一个指针</strong>：“输出太长，已存到 <code>/tmp/xxx</code>，前 50 行如下……需要完整内容请用 <code>read_file</code> 读取。”</li></ol><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> budgetResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">tool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">fullText</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (fullText.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tool.maxResultSizeChars) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fullText</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> writeToTemp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fullText)                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 完整结果存盘</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> preview</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fullText.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tool.maxResultSizeChars)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[输出过长,已截断。完整内容(${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fullText</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">} 字符)见 ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">},可用 read_file 读取。]`</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>这一招的精妙之处：信息没有丢，只是从“上下文里”挪到了“够得着的地方”。</strong> 模型依然知道有这么个结果、知道它的开头、知道完整版在哪——真需要细节时，它能自己去 <code>read_file</code> 取回来。你用一个廉价的“指针”换掉了昂贵的“全文”，而且<strong>把要不要花上下文去看全文的决定权交还给了模型</strong>。这比一刀切地截断(直接丢掉后半截、模型永远够不着了)高明得多。</p></div><p>注意这又是<a href="/Front2Full/manual/agent/llm-to-agent/tool-abstraction">04 篇“两个受众”</a>的体现：<strong>给模型的是截断预览，给人的 UI 里仍可展示完整输出</strong>——人看到的和模型看到的，本就该是两个版本。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>一个反直觉的边界：<strong>有些工具的结果绝不能外置</strong>。典型就是 <code>read_file</code> 自己——如果它的输出也被“存盘 + 让你用 read_file 去读”，就成了一个 <code>read_file → 存盘 → read_file → ……</code> 的死循环。所以这类工具要把上限设成“无穷大”(它自己已经通过别的方式自我约束了)。<strong>设预算时，先想清楚这个工具的结果被外置后，会不会绕回来咬自己。</strong></p></div><h3 id="手术刀二-microcompact-——-按-tool-use-id-定点删除" tabindex="-1">手术刀二：microcompact —— 按 <code>tool_use_id</code> 定点删除 <a class="header-anchor" href="#手术刀二-microcompact-——-按-tool-use-id-定点删除" aria-label="Permalink to &quot;手术刀二：microcompact —— 按 `tool_use_id` 定点删除&quot;">​</a></h3><p>第二把刀更精细：<strong>在不动对话其余部分的前提下，把某几个特定的、老的工具结果“就地掏空”。</strong></p><p>关键抓手是 <code>tool_use_id</code>(<a href="/Front2Full/manual/agent/llm-to-agent/tool-use">02 篇</a>那个配对 ID)。你可以精确地定位到“第 8 轮那次 <code>read_file</code> 的结果”，把它的 <code>content</code> 替换成一个小占位符(“[早期输出已省略]”)，而<strong>保持 <code>tool_use</code> / <code>tool_result</code> 的配对结构完好</strong>(不破坏<a href="/Front2Full/manual/agent/llm-to-agent/interrupt">历史合法性</a>)：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>掏空前:...[tool_use:read_file][tool_result: &lt;5000 行文件内容&gt;]...</span></span>\n<span class="line"><span>掏空后:...[tool_use:read_file][tool_result: &quot;[早期文件内容已省略,如需请重读]&quot;]...</span></span>\n<span class="line"><span>        └─ 配对结构、id、位置全都不变,只有 content 被换小了 ─┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>为什么值得这么费劲地“定点”？为了<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">缓存</a>。</strong> 全量压缩重写了边界后的一切，缓存从边界起全废。而 microcompact 只改动<strong>特定几个、而且尽量是很老的</strong> <code>tool_use_id</code>——如果被改的都在缓存前缀的很靠前处(本来也快过期)，对热缓存的破坏就降到最低。<strong>这是“减负”和“保缓存”两个目标之间的精细平衡</strong>：能定点切除，就别整段推平。挑“老的、大的、且已经不太可能再被用到的”结果下刀，收益最大、代价最小。</p></div><h3 id="手术刀三-内容外置引用" tabindex="-1">手术刀三：内容外置引用 <a class="header-anchor" href="#手术刀三-内容外置引用" aria-label="Permalink to &quot;手术刀三：内容外置引用&quot;">​</a></h3><p>第三把刀是前两把的一般化：<strong>大块内容根本不进上下文，而是活在外部，只在上下文里留一个句柄(handle)，模型按需拉取。</strong></p><p>这适合那些“可能要用、但大概率不用全部”的大数据：一次大规模搜索的完整结果、一个大目录的完整清单、一份长文档。上下文里只放“有这么个东西，句柄是 X”，模型真要用时通过工具把它(或它的一部分)取回来。<strong>本质上，这是把上下文当“寄存器”，把外部存储当“内存”，按需换入换出</strong>——和操作系统管理内存的思路如出一辙。</p><h2 id="三、一条统领性原则-用最小破坏换取足够空间" tabindex="-1">三、一条统领性原则：用最小破坏换取足够空间 <a class="header-anchor" href="#三、一条统领性原则-用最小破坏换取足够空间" aria-label="Permalink to &quot;三、一条统领性原则：用最小破坏换取足够空间&quot;">​</a></h2><p>三把刀，加上<a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">全量压缩</a>，构成一个<strong>从轻到重</strong>的减负梯度：</p><table tabindex="0"><thead><tr><th>手段</th><th>破坏性</th><th>何时用</th></tr></thead><tbody><tr><td>工具结果预算</td><td>最小(源头就截)</td><td>每个大结果产生时，预防性地</td></tr><tr><td>microcompact 定点删除</td><td>小(只动几个老结果)</td><td>上下文偏高，且膨胀源集中在几个胖子</td></tr><tr><td>内容外置引用</td><td>小(数据本就在外部)</td><td>已知会产生大数据的工具</td></tr><tr><td>全量压缩</td><td>大(推平一段 + 废缓存)</td><td>前几招都不够，历史整体太长</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>原则：永远优先用能腾出足够空间的、破坏性最小的那一招。</strong> 别一上来就全量压缩——先看看是不是几个巨型工具结果在作祟，能定点切除就定点切除；实在是“整体都长了”，才动用压缩这把钝器。这个“阶梯式减负”的思路，是精细上下文管理的核心心法。一个成熟的 Agent 会把这几招组合起来，层层递进地维持上下文健康，而不是简单粗暴地一压了之。</p></div><h2 id="四、第五阶段总结-上下文工程全景" tabindex="-1">四、第五阶段总结：上下文工程全景 <a class="header-anchor" href="#四、第五阶段总结-上下文工程全景" aria-label="Permalink to &quot;四、第五阶段总结：上下文工程全景&quot;">​</a></h2><p><strong>第五阶段到此完整。</strong> 这是整个专栏里格外硬核的一章，值得把五篇串起来回望——它们共同回答了那个核心问题：<strong>在有限的窗口里，如何始终装着模型此刻最需要的东西？</strong></p><table tabindex="0"><thead><tr><th>篇章</th><th>在这场战争里的角色</th></tr></thead><tbody><tr><td><a href="/Front2Full/manual/agent/llm-to-agent/token-budget">10 Token 预算</a></td><td>侦察：量出用量，设水位线</td></tr><tr><td><a href="/Front2Full/manual/agent/llm-to-agent/context-injection">11 上下文注入</a></td><td>编排：每轮的上下文是分层拼出来的</td></tr><tr><td><a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">12 Prompt 缓存</a></td><td>省：稳定前缀复用，守住字节红线</td></tr><tr><td><a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">13 自动压缩</a></td><td>减(钝器)：历史太长，折叠成摘要</td></tr><tr><td><strong>14 精细化管理</strong></td><td>减(手术刀)：定点切除胖子，少伤缓存</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>如果这一整章只留一句话：<strong>上下文是 Agent 最稀缺的资源，而管理它是一组互相拉扯的权衡</strong>——省(缓存)要字节稳定，减(压缩)必然破坏字节；要空间就得牺牲细节，要细节就得占空间。没有银弹，只有针对具体情形的、在多个约束间的通盘取舍。<strong>这也是为什么“上下文工程”是区分玩具 Agent 和生产 Agent 的分水岭。</strong></p></div><h2 id="五、下一站" tabindex="-1">五、下一站 <a class="header-anchor" href="#五、下一站" aria-label="Permalink to &quot;五、下一站&quot;">​</a></h2><p>上下文管住了，我们的 Agent 已经能撑起很长的任务而不崩。但真实世界还有另一类挑战我们一直在往后推：<strong>各种各样的失败</strong>——网络抖动、限流、模型过载、输出被截断。下一篇进入<a href="/Front2Full/manual/agent/llm-to-agent/error-recovery">第六阶段：健壮性</a>，看一个生产级 Agent 如何把“出错”当成常态来优雅应对。</p><hr><p><strong>本篇对应代码</strong>：配套仓库加入 <code>src/toolResultBudget.ts</code>(工具结果超限外置)，并给工具接口补上 <code>maxResultSizeChars</code>。<code>git checkout article-14</code>。</p>',35)])])}const g=a(e,[["render",l]]);export{k as __pageData,g as default};
